import type en from "@/messages/en.json";
import type { Language } from "./language";

// Every key and ICU argument is typed from the English catalogue (add-language-system D3), so a missing key or
// argument fails `npm run type-check`; `en.d.json.ts` is generated by the next-intl plugin.
declare module "next-intl" {
  interface AppConfig {
    Locale: Language;
    Messages: typeof en;
  }
}
